The DHT22 sensor is a popular temperature and humidity sensor used in many DIY projects and IoT applications. Calibration is necessary to ensure accurate readings from the sensor. Here's an example code in Arduino to perform calibration:

**Note:** Before running this code, make sure you have the DHT library installed in your Arduino IDE. You can install it from the Library Manager or download it from the official DHT library website.

**Calibration Code:**
```cpp
#include <DHT.h>

#define DHT_PIN 2 // Pin connected to DHT22 sensor

DHT dht(DHT_PIN, DHT22);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  int sensorValue = dht.readHumidity();
  int sensorTemp = dht.readTemperature();

  // Print sensor values to serial monitor
  Serial.print("Humidity: ");
  Serial.print(sensorValue);
  Serial.print(" %, Temperature: ");
  Serial.print(sensorTemp);
  Serial.println(" *C");

  // Wait 2 seconds before taking the next reading
  delay(2000);
}
```
