```javascript
// Set the initial conditions
let angle = 20; // initial angle in degrees
let velocity = 0; // initial velocity

// Set the gravity and the length of the pendulum
let g = 9.81; // gravity in meters per second squared
let l = 100; // length of the pendulum in pixels

// Set the canvas dimensions
let canvas = document.getElementById('canvas');
let ctx = canvas.getContext('2d');
let canvasWidth = canvas.offsetWidth;
let canvasHeight = canvas.offsetHeight;

// Update the simulation
function update() {
    // Calculate the acceleration of the pendulum due to gravity
    let acceleration = -g / l * Math.sin(Math.PI * angle / 180);

    // Update the velocity
    velocity += acceleration;

    // Update the angle
    angle += velocity;

    // Update the simulation at the next frame
    requestAnimationFrame(() => {
        update();
    });
}

// Draw the pendulum
function draw() {
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    // Draw the pendulum arm
    let x = canvasWidth / 2;
    let y = canvasHeight / 2 - l * Math.sin(Math.PI * angle / 180);
    ctx.beginPath();
    ctx.arc(x, y, 10, 0, Math.PI * 2);
    ctx.fillStyle = 'black';
    ctx.fill();

    // Draw the bob
    x = canvasWidth / 2;
    y = canvasHeight / 2;
    ctx.beginPath();
    ctx.arc(x, y, 20, 0, Math.PI * 2);
    ctx.fillStyle = 'red';
    ctx.fill();
}

// Main
let running = false;

document.getElementById('start').addEventListener('click', () => {
    running = true;
    update();
    draw();
});

document.getElementById('stop').addEventListener('click', () => {
    running = false;
});

// Set the initial angle and velocity
document.getElementById('angle-input').addEventListener('input', () => {
    angle = parseInt(document.getElementById('angle-input').value);
});

// Start the simulation when the document is loaded
document.addEventListener('DOMContentLoaded', () => {
    document.getElementById('start').addEventListener('click', () => {
        running = true;
    });
});
